-- KANDIDATENS TAKT (NIVA2-LIVE steg 7, DECISIONS #200, #573, #583). Hur ofta kandidatens betavarning skulle tala per körning, ur
-- skuggans logg shadow_log.kandidat: varje rad i h är en passage, en sträcka där kandidatens regel varnar och som rutten passerar
-- (engine/src/segment.ts kandidatLangsRutten: [t s från start vid 80 km/h, sträcka, km längs, avstånd km, punkter]).
-- Skuggan kör 3 av de 20 svenska rutterna per halvtimme (rotationen i skuggmotor/main.ts), så varje rutt körs var 3,5 timme.
-- Samma sträcka kan inte tala två gånger inom 10 min / 5 km (motorn), så en följd är två OLIKA sträckor i samma körning.
-- Provläsningen 16/10 och huvudläsningen före App Review kör samma rader. Körs med DB-knappens läsläge, en sats per rad nedan
-- (kommentarraderna skickas inte med); bara aggregat skrivs ut, och ingen rad läser cron.job.
SELECT count(*) AS korningar, min(s.run_at) AS fran, max(s.run_at) AS till, count(DISTINCT s.route) AS rutter, count(*) FILTER (WHERE (s.kandidat->>'n')::int > 0) AS regeln_varnade, count(*) FILTER (WHERE s.kandidat ? 'skal') AS med_skal, count(*) FILTER (WHERE jsonb_array_length(s.kandidat->'h') > 0) AS med_passage, sum(jsonb_array_length(s.kandidat->'h')) AS passager, count(DISTINCT date_trunc('day', s.run_at)) FILTER (WHERE jsonb_array_length(s.kandidat->'h') > 0) AS dygn_med_passage FROM shadow_log s WHERE s.land = 'SE' AND s.kandidat ? 'h'
SELECT s.route, count(*) AS korningar, count(*) FILTER (WHERE jsonb_array_length(s.kandidat->'h') > 0) AS med_passage, sum(jsonb_array_length(s.kandidat->'h')) AS passager, max(jsonb_array_length(s.kandidat->'h')) AS max_per_korning FROM shadow_log s WHERE s.land = 'SE' AND s.kandidat ? 'h' GROUP BY s.route HAVING sum(jsonb_array_length(s.kandidat->'h')) > 0 ORDER BY 4 DESC
WITH p AS (SELECT s.id, (e->>0)::int AS t FROM shadow_log s, jsonb_array_elements(s.kandidat->'h') e WHERE s.land = 'SE' AND s.kandidat ? 'h'), g AS (SELECT t - lag(t) OVER (PARTITION BY id ORDER BY t) AS d FROM p) SELECT count(d) AS foljder, min(d) AS tatast_s, count(*) FILTER (WHERE d <= 120) AS inom_2min, count(*) FILTER (WHERE d <= 300) AS inom_5min, count(*) FILTER (WHERE d <= 600) AS inom_10min, round(100.0 * count(*) FILTER (WHERE d <= 600) / nullif(count(d), 0), 1) AS andel_inom_10min, percentile_cont(0.5) WITHIN GROUP (ORDER BY d) AS median_s FROM g WHERE d IS NOT NULL
WITH p AS (SELECT s.alerts, (e->>0)::int AS t, e->>1 AS seg FROM shadow_log s, jsonb_array_elements(s.kandidat->'h') e WHERE s.land = 'SE' AND s.kandidat ? 'h') SELECT count(*) AS passager, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(p.alerts) a WHERE a->>'id' = 'seg:' || p.seg)) AS samma_stracka_halka, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(p.alerts) a WHERE abs((a->>'t')::numeric - p.t) <= 10)) AS annan_inom_10s, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(p.alerts) a WHERE abs((a->>'t')::numeric - p.t) <= 60)) AS annan_inom_60s FROM p
WITH p AS (SELECT s.alerts, (e->>0)::int AS t, e->>1 AS seg FROM shadow_log s, jsonb_array_elements(s.kandidat->'h') e WHERE s.land = 'SE' AND s.kandidat ? 'h') SELECT count(*) AS fall, min(p.t - (a->>'t')::numeric) AS min_efter_a1_s, max(p.t - (a->>'t')::numeric) AS max_efter_a1_s, count(*) FILTER (WHERE p.t - (a->>'t')::numeric BETWEEN 0 AND 120) AS inom_2min_efter_a1 FROM p, jsonb_array_elements(p.alerts) a WHERE a->>'id' = 'seg:' || p.seg
SELECT date_trunc('hour', s.run_at) AS timme, count(*) FILTER (WHERE jsonb_array_length(s.kandidat->'h') > 0) AS rutter_med_passage, sum(jsonb_array_length(s.kandidat->'h')) AS passager, max((s.kandidat->>'n')::int) AS varnande_punkter FROM shadow_log s WHERE s.land = 'SE' AND s.kandidat ? 'h' GROUP BY 1 HAVING sum(jsonb_array_length(s.kandidat->'h')) > 0 ORDER BY 1
